19	std::vector<at::Tensor> split(const at::Tensor &input, int64_t split_size, int64_t dim) {
20	    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
21	                "split: input must be on NPU device");
22	    TORCH_CHECK(split_size > 0, "split: split_size must be > 0");
23	
24	    int64_t ndim = input.dim();
25	    int64_t dimIdx = dim;
26	    if (dimIdx < 0) {
27	        dimIdx += ndim;
28	    }
29	    TORCH_CHECK(dimIdx >= 0 && dimIdx < ndim,
30	                "split: dim out of range, got dim=", dim, " for tensor with ", ndim, " dims");
31	
32	    TORCH_CHECK(input.scalar_type() == at::kFloat ||
33	                input.scalar_type() == at::kHalf ||
34	                input.scalar_type() == at::kBFloat16,
35	                "split: only float32, float16 and bfloat16 are supported");
36	
37	    at::Tensor inputContiguous = input.contiguous();
38	    int64_t dimSize = inputContiguous.size(dimIdx);
39	
40	    // Compute number of chunks
41	    int64_t chunkCount = (dimSize + split_size - 1) / split_size;
42	
43	    // Create output tensors
44	    std::vector<at::Tensor> outputs;
45	    outputs.reserve(chunkCount);
46	    int64_t remaining = dimSize;
47	    for (int64_t i = 0; i < chunkCount; i++) {
48	        int64_t curSplitSize = std::min(split_size, remaining);
49	        remaining -= curSplitSize;
50	
51	        // Use narrow + contiguous to extract chunk on NPU
52	        at::Tensor chunk = inputContiguous.narrow(dimIdx,
53	            (i * split_size < dimSize ? i * split_size : dimSize), curSplitSize).contiguous();
54	
55	        outputs.push_back(chunk);
56	    }
57	
58	    return outputs;
59	}
