13	constexpr int32_t BUFFER_NUM = 2;
14	
15	class SplitKernel {
16	public:
17	    __aicore__ inline SplitKernel() {}
18	
19	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, uint32_t length)
20	    {
21	        this->length_ = length;
22	        this->blockLength = length;
23	        this->tileNum = 1;
24	        this->tileLength = length_;
25	
26	        xGm.SetGlobalBuffer((__gm__ half*)input, this->blockLength);
27	        zGm.SetGlobalBuffer((__gm__ half*)output, this->blockLength);
28	
29	        pipe.InitBuffer(inQueue, BUFFER_NUM, this->tileLength * sizeof(half));
30	        pipe.InitBuffer(outQueue, BUFFER_NUM, this->tileLength * sizeof(half));
31	    }
32	
33	    __aicore__ inline void Process()
34	    {
35	        CopyIn(0);
36	        Compute(0);
37	        CopyOut(0);
38	    }
39	
40	private:
41	    __aicore__ inline void CopyIn(uint32_t progress)
42	    {
43	        AscendC::LocalTensor<half> xLocal = inQueue.AllocTensor<half>();
44	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], this->tileLength);
45	        inQueue.EnQue(xLocal);
46	    }
47	
48	    __aicore__ inline void Compute(uint32_t progress)
49	    {
50	        AscendC::LocalTensor<half> xLocal = inQueue.DeQue<half>();
51	        AscendC::LocalTensor<half> zLocal = outQueue.AllocTensor<half>();
52	        AscendC::DataCopy(zLocal, xLocal, this->tileLength);
53	        outQueue.EnQue<half>(zLocal);
54	        inQueue.FreeTensor(xLocal);
55	    }
56	
57	    __aicore__ inline void CopyOut(uint32_t progress)
58	    {
59	        AscendC::LocalTensor<half> zLocal = outQueue.DeQue<half>();
60	        AscendC::DataCopy(zGm[progress * this->tileLength], zLocal, this->tileLength);
61	        outQueue.FreeTensor(zLocal);
62	    }
63	
64	private:
65	    AscendC::TPipe pipe;
66	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue;
67	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
68	    AscendC::GlobalTensor<half> xGm;
69	    AscendC::GlobalTensor<half> zGm;
70	    uint32_t length_;
71	    uint32_t blockLength;
72	    uint32_t tileNum;
73	    uint32_t tileLength;
74	};
