#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

class KernelSplit {
public:
    __aicore__ inline KernelSplit() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, uint32_t length)
    {
        this->blockLength_ = length;
        if (this->blockLength_ > 0) {
            this->tileNum_ = 1;
            this->tileLength_ = this->blockLength_;

            xGm_.SetGlobalBuffer((__gm__ half*)input, this->blockLength_);
            zGm_.SetGlobalBuffer((__gm__ half*)output, this->blockLength_);

            pipe_.InitBuffer(inQueue_, BUFFER_NUM, this->tileLength_ * sizeof(half));
            pipe_.InitBuffer(outQueue_, BUFFER_NUM, this->tileLength_ * sizeof(half));
        }
    }

    __aicore__ inline void Process()
    {
        if (this->blockLength_ == 0) return;
        CopyIn(0);
        CopyOut(0);
    }

private:
    __aicore__ inline void CopyIn(uint32_t progress)
    {
        AscendC::LocalTensor<half> xLocal = inQueue_.AllocTensor<half>();
        AscendC::DataCopy(xLocal, xGm_[progress * this->tileLength_], this->tileLength_);
        inQueue_.EnQue(xLocal);
    }

    __aicore__ inline void CopyOut(uint32_t progress)
    {
        AscendC::LocalTensor<half> zLocal = inQueue_.DeQue<half>();
        AscendC::DataCopy(zGm_[progress * this->tileLength_], zLocal, this->tileLength_);
        inQueue_.FreeTensor(zLocal);
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::GlobalTensor<half> xGm_;
    AscendC::GlobalTensor<half> zGm_;
    uint32_t blockLength_;
    uint32_t tileNum_;
    uint32_t tileLength_;
};

extern "C" __global__ __aicore__ void kernel_split(
    GM_ADDR input,
    GM_ADDR output,
    uint32_t length,
    uint32_t inputOffset,
    uint32_t outputOffset)
{
    KernelSplit op;
    (void)inputOffset;
    (void)outputOffset;
    op.Init(input, output, length);
    op.Process();
}
