#include "torch_kernel_helper.h"
#include <ATen/ATen.h>
#include <torch/extension.h>
#include <algorithm>
#include <vector>

namespace ascend_kernel {

std::vector<at::Tensor> split(const at::Tensor &input, int64_t split_size, int64_t dim) {
    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
                "split: input must be on NPU device");
    TORCH_CHECK(split_size > 0, "split: split_size must be > 0");

    int64_t ndim = input.dim();
    int64_t dimIdx = dim;
    if (dimIdx < 0) {
        dimIdx += ndim;
    }
    TORCH_CHECK(dimIdx >= 0 && dimIdx < ndim,
                "split: dim out of range, got dim=", dim, " for tensor with ", ndim, " dims");

    TORCH_CHECK(input.scalar_type() == at::kFloat ||
                input.scalar_type() == at::kHalf ||
                input.scalar_type() == at::kBFloat16,
                "split: only float32, float16 and bfloat16 are supported");

    at::Tensor inputContiguous = input.contiguous();
    int64_t dimSize = inputContiguous.size(dimIdx);

    // Compute number of chunks
    int64_t chunkCount = (dimSize + split_size - 1) / split_size;

    // Create output tensors
    std::vector<at::Tensor> outputs;
    outputs.reserve(chunkCount);
    int64_t remaining = dimSize;
    for (int64_t i = 0; i < chunkCount; i++) {
        int64_t curSplitSize = std::min(split_size, remaining);
        remaining -= curSplitSize;

        // Use narrow + contiguous to extract chunk on NPU
        at::Tensor chunk = inputContiguous.narrow(dimIdx,
            (i * split_size < dimSize ? i * split_size : dimSize), curSplitSize).contiguous();

        outputs.push_back(chunk);
    }

    return outputs;
}

}  // namespace ascend_kernel
